package composer

import (
	"io/fs"
	"net/url"
	"os"
	"path/filepath"
	"strconv"
	"strings"

	"github.com/TrebuchetDynamics/gormes-agent/internal/llm"
)

const (
	defaultLargePasteChars = 8000
	defaultLargePasteLines = 80
)

// ComposerDropOptions holds the injectable filesystem context for
// DetectComposerDroppedFile. Tests use HomeDir to keep "~" expansion away
// from the real operator home.
type ComposerDropOptions struct {
	HomeDir string
	Stat    func(string) (fs.FileInfo, error)
}

// ComposerDropResult is the native TUI equivalent of Hermes'
// _detect_file_drop result.
type ComposerDropResult struct {
	Matched   bool
	Path      string
	IsImage   bool
	Remainder string
	Evidence  string
}

// ComposerPasteOptions holds the injectable long-paste collapse seam.
type ComposerPasteOptions struct {
	Collapse        func(string) (string, error)
	LargePasteChars int
	LargePasteLines int
}

// ComposerPasteSnippet tracks the original paste content behind a readable
// composer token.
type ComposerPasteSnippet struct {
	Label string
	Text  string
	Path  string
}

// ComposerPasteResult is returned after classifying pasted text.
type ComposerPasteResult struct {
	InsertText string
	Snippet    *ComposerPasteSnippet
	Evidence   string
}

// ComposerCopyResult is the pure result behind /copy [number].
type ComposerCopyResult struct {
	OK             bool
	Text           string
	ResponseNumber int
	Evidence       string
}

// DetectComposerDroppedFile detects a pasted or dropped local file path
// without treating short slash commands like /help as files.
func DetectComposerDroppedFile(input string, opts ComposerDropOptions) ComposerDropResult {
	trimmed := strings.TrimSpace(input)
	if trimmed == "" || strings.Contains(trimmed, "\n") || !LooksLikeComposerDroppedPath(trimmed) {
		return ComposerDropResult{}
	}
	stat := opts.Stat
	if stat == nil {
		stat = os.Stat
	}

	for _, c := range composerDropCandidates(trimmed) {
		path, ok := normalizeComposerDropPath(c.raw, opts.HomeDir)
		if !ok {
			continue
		}
		info, err := stat(path)
		if err != nil || info.IsDir() {
			continue
		}
		return ComposerDropResult{
			Matched:   true,
			Path:      path,
			IsImage:   IsComposerImagePath(path),
			Remainder: strings.TrimSpace(c.remainder),
		}
	}
	return ComposerDropResult{Evidence: "tui_ingress_file_missing"}
}

// LooksLikeComposerDroppedPath mirrors the current Hermes Ink client-side
// heuristic: enough to decide whether to ask the gateway to validate a path,
// not enough to claim a real file exists.
func LooksLikeComposerDroppedPath(text string) bool {
	trimmed := strings.TrimSpace(text)
	if trimmed == "" || strings.Contains(trimmed, "\n") {
		return false
	}
	if strings.HasPrefix(trimmed, "file://") ||
		strings.HasPrefix(trimmed, "~/") ||
		strings.HasPrefix(trimmed, "./") ||
		strings.HasPrefix(trimmed, "../") ||
		hasQuotedComposerPathPrefix(trimmed) ||
		hasWindowsDrivePrefix(trimmed) ||
		hasQuotedWindowsDrivePrefix(trimmed) {
		return true
	}
	if strings.HasPrefix(trimmed, "/") {
		rest := strings.TrimPrefix(trimmed, "/")
		return strings.Contains(rest, "/") || strings.Contains(rest, ".")
	}
	return false
}

// IsComposerImagePath reports whether path has a Hermes-supported image
// suffix. Header validation happens later at the gateway/image metadata seam.
func IsComposerImagePath(path string) bool {
	switch strings.ToLower(filepath.Ext(path)) {
	case ".png", ".jpg", ".jpeg", ".gif", ".webp", ".bmp", ".tiff", ".tif", ".svg", ".ico":
		return true
	default:
		return false
	}
}

// CollapseComposerPaste returns either the original small paste text or a
// readable placeholder plus a snippet that can be expanded before external
// editor submission.
func CollapseComposerPaste(text string, opts ComposerPasteOptions) ComposerPasteResult {
	cleaned := stripTrailingComposerPasteNewlines(text)
	if cleaned == "" || !strings.ContainsAny(cleaned, " \t\r\n") {
		return ComposerPasteResult{InsertText: cleaned}
	}
	lineCount := composerLineCount(cleaned)
	maxChars := opts.LargePasteChars
	if maxChars <= 0 {
		maxChars = defaultLargePasteChars
	}
	maxLines := opts.LargePasteLines
	if maxLines <= 0 {
		maxLines = defaultLargePasteLines
	}
	if len(cleaned) < maxChars && lineCount < maxLines {
		return ComposerPasteResult{InsertText: cleaned}
	}

	label := composerPasteTokenLabel(cleaned, lineCount)
	snippet := &ComposerPasteSnippet{Label: label, Text: cleaned}
	result := ComposerPasteResult{InsertText: label, Snippet: snippet}
	if opts.Collapse == nil {
		return result
	}
	path, err := opts.Collapse(cleaned)
	if err != nil {
		result.Evidence = "tui_ingress_paste_collapse_failed"
		return result
	}
	snippet.Path = path
	return result
}

// ExpandComposerPasteSnippets replaces visible paste tokens with their stored
// content before an injected external-editor buffer is opened.
func ExpandComposerPasteSnippets(input string, snippets []ComposerPasteSnippet, readFile func(string) ([]byte, error)) (string, error) {
	out := input
	for _, snip := range snippets {
		if snip.Label == "" || !strings.Contains(out, snip.Label) {
			continue
		}
		text := snip.Text
		if text == "" && snip.Path != "" && readFile != nil {
			body, err := readFile(snip.Path)
			if err != nil {
				return "", err
			}
			text = string(body)
		}
		out = strings.ReplaceAll(out, snip.Label, text)
	}
	return out, nil
}

// RecoverComposerBracketedPaste turns terminal bracketed-paste sequences back
// into normal text, including the unterminated form produced by broken
// terminals after a paste interruption.
func RecoverComposerBracketedPaste(input string) string {
	const begin = "\x1b[200~"
	const end = "\x1b[201~"
	out := strings.ReplaceAll(input, begin, "")
	out = strings.ReplaceAll(out, end, "")
	return out
}

// SelectComposerCopyText selects the latest or indexed assistant response and
// removes reasoning scratchpads before it reaches the clipboard seam.
func SelectComposerCopyText(history []llm.Message, arg string) ComposerCopyResult {
	assistant := make([]llm.Message, 0, len(history))
	for _, msg := range history {
		if msg.Role == "assistant" {
			assistant = append(assistant, msg)
		}
	}
	if len(assistant) == 0 {
		return ComposerCopyResult{Evidence: "tui_ingress_copy_empty"}
	}

	if strings.TrimSpace(arg) != "" {
		n, err := strconv.Atoi(strings.TrimSpace(arg))
		if err != nil || n < 1 || n > len(assistant) {
			return ComposerCopyResult{Evidence: "tui_ingress_copy_invalid_index"}
		}
		text := strings.TrimSpace(StripComposerReasoningBlocks(assistant[n-1].Content))
		if text == "" {
			return ComposerCopyResult{Evidence: "tui_ingress_copy_empty_response", ResponseNumber: n}
		}
		return ComposerCopyResult{OK: true, Text: text, ResponseNumber: n}
	}

	for i := len(assistant) - 1; i >= 0; i-- {
		text := strings.TrimSpace(StripComposerReasoningBlocks(assistant[i].Content))
		if text != "" {
			return ComposerCopyResult{OK: true, Text: text, ResponseNumber: i + 1}
		}
	}
	return ComposerCopyResult{Evidence: "tui_ingress_copy_empty"}
}

// StripComposerReasoningBlocks removes common reasoning/thinking XML blocks
// from assistant text before clipboard copy.
func StripComposerReasoningBlocks(text string) string {
	cleaned := text
	for _, tag := range []string{"reasoning_scratchpad", composerThinkTag(), composerThinkingTag(), "reasoning", "thought"} {
		cleaned = stripComposerTagBlock(cleaned, tag)
	}
	return cleaned
}

func composerThinkTag() string {
	return string([]byte{'t', 'h', 'i', 'n', 'k'})
}

func composerThinkingTag() string {
	return string([]byte{'t', 'h', 'i', 'n', 'k', 'i', 'n', 'g'})
}

func stripComposerTagBlock(text, tag string) string {
	open := "<" + tag + ">"
	close := "</" + tag + ">"
	cleaned := text
	for {
		lower := strings.ToLower(cleaned)
		start := strings.Index(lower, open)
		if start < 0 {
			break
		}
		afterOpen := start + len(open)
		relEnd := strings.Index(lower[afterOpen:], close)
		if relEnd < 0 {
			cleaned = cleaned[:start]
			break
		}
		end := afterOpen + relEnd + len(close)
		cleaned = cleaned[:start] + cleaned[end:]
	}
	for {
		lower := strings.ToLower(cleaned)
		idx := strings.Index(lower, close)
		if idx < 0 {
			break
		}
		cleaned = cleaned[:idx] + cleaned[idx+len(close):]
	}
	return cleaned
}

func stripTrailingComposerPasteNewlines(text string) string {
	if !strings.ContainsFunc(text, func(r rune) bool { return r != '\n' }) {
		return text
	}
	return strings.TrimRight(text, "\n")
}

func composerLineCount(text string) int {
	if text == "" {
		return 0
	}
	return strings.Count(text, "\n") + 1
}

func composerPasteTokenLabel(text string, lineCount int) string {
	preview := composerPasteTokenPreview(text)
	if preview == "" {
		return "[[ [" + intString(lineCount) + " lines] ]]"
	}
	return "[[ " + preview + " [" + intString(lineCount) + " lines] ]]"
}

func composerPasteTokenPreview(text string) string {
	preview := strings.TrimSpace(strings.ReplaceAll(text, "\n", " "))
	runes := []rune(preview)
	if len(runes) <= 48 {
		return preview
	}
	return strings.TrimSpace(string(runes[:24])) + ".. " + strings.TrimSpace(string(runes[len(runes)-18:]))
}

func intString(n int) string {
	if n == 0 {
		return "0"
	}
	var buf [20]byte
	i := len(buf)
	for n > 0 {
		i--
		buf[i] = byte('0' + n%10)
		n /= 10
	}
	return string(buf[i:])
}

type composerDropCandidate struct {
	raw       string
	remainder string
}

func composerDropCandidates(input string) []composerDropCandidate {
	if q := input[0]; q == '"' || q == '\'' {
		if end := strings.IndexByte(input[1:], q); end >= 0 {
			pos := end + 1
			return []composerDropCandidate{{
				raw:       input[1:pos],
				remainder: strings.TrimSpace(input[pos+1:]),
			}}
		}
	}

	candidates := make([]composerDropCandidate, 0, composerDropBoundaryCount(input)+1)
	for end := len(input); end > 0; end-- {
		if end != len(input) && !isComposerDropRemainderBoundary(input[end]) {
			continue
		}
		raw := strings.TrimSpace(input[:end])
		if raw == "" {
			continue
		}
		candidates = append(candidates, composerDropCandidate{
			raw:       raw,
			remainder: strings.TrimSpace(input[end:]),
		})
	}
	return candidates
}

func composerDropBoundaryCount(input string) int {
	count := 0
	for i := 0; i < len(input); i++ {
		if isComposerDropRemainderBoundary(input[i]) {
			count++
		}
	}
	return count
}

func isComposerDropRemainderBoundary(b byte) bool {
	return b == ' ' || b == '\t'
}

func normalizeComposerDropPath(raw, home string) (string, bool) {
	path := strings.TrimSpace(raw)
	if path == "" {
		return "", false
	}
	path = strings.ReplaceAll(path, `\ `, " ")

	if strings.HasPrefix(path, "file://") {
		u, err := url.Parse(path)
		if err != nil || (u.Host != "" && u.Host != "localhost") {
			return "", false
		}
		decoded, err := url.PathUnescape(u.EscapedPath())
		if err != nil {
			return "", false
		}
		path = decoded
	}

	if path == "~" {
		if home == "" {
			return "", false
		}
		path = home
	} else if strings.HasPrefix(path, "~/") || strings.HasPrefix(path, `~\`) {
		if home == "" {
			return "", false
		}
		path = filepath.Join(home, path[2:])
	}

	return filepath.Clean(path), true
}

func hasQuotedComposerPathPrefix(s string) bool {
	if len(s) < 2 || (s[0] != '"' && s[0] != '\'') {
		return false
	}
	quoted := s[1:]
	return strings.HasPrefix(quoted, "/") ||
		strings.HasPrefix(quoted, "~/") ||
		strings.HasPrefix(quoted, `~\`) ||
		strings.HasPrefix(quoted, "./") ||
		strings.HasPrefix(quoted, "../")
}

func hasWindowsDrivePrefix(s string) bool {
	return len(s) >= 3 && isASCIIDriveLetter(s[0]) && s[1] == ':' && (s[2] == '/' || s[2] == '\\')
}

func hasQuotedWindowsDrivePrefix(s string) bool {
	return len(s) >= 4 && (s[0] == '"' || s[0] == '\'') && hasWindowsDrivePrefix(s[1:])
}

func isASCIIDriveLetter(b byte) bool {
	return (b >= 'a' && b <= 'z') || (b >= 'A' && b <= 'Z')
}

package composer

import (
	"fmt"
	"strings"

	"github.com/TrebuchetDynamics/gormes-agent/internal/llm"
)

// CopySlashResult is the pure slash-command decision behind /copy. When
// WriteClipboard is true, root package tui writes Text through its injected
// clipboard seam and maps any host error to a visible status.
type CopySlashResult struct {
	Handled        bool
	WriteClipboard bool
	Text           string
	Status         string
}

// HandleCopySlash parses /copy [number], selects visible assistant text, and
// returns the status text to show when no clipboard write should be attempted.
func HandleCopySlash(input string, history []llm.Message, clipboardAvailable bool) CopySlashResult {
	if !clipboardAvailable {
		return CopySlashResult{Handled: true, Status: "copy: clipboard unavailable"}
	}
	fields := strings.Fields(input)
	arg := ""
	if len(fields) > 1 {
		arg = fields[1]
	}
	result := SelectComposerCopyText(history, arg)
	if !result.OK {
		return CopySlashResult{Handled: true, Status: copyStatusForEvidence(result)}
	}
	return CopySlashResult{
		Handled:        true,
		WriteClipboard: true,
		Text:           result.Text,
		Status:         fmt.Sprintf("Copied assistant response #%d to clipboard", result.ResponseNumber),
	}
}

func copyStatusForEvidence(result ComposerCopyResult) string {
	switch result.Evidence {
	case "tui_ingress_copy_invalid_index":
		return "copy: invalid response number"
	case "tui_ingress_copy_empty_response":
		return fmt.Sprintf("copy: assistant response #%d has no visible text", result.ResponseNumber)
	default:
		return "copy: nothing to copy"
	}
}

package composer

import (
	"strings"

	"github.com/TrebuchetDynamics/gormes-agent/internal/tui/envmap"
)

// CanFastAppendShape mirrors Hermes' conservative fast-echo append gate. It
// only allows one-line printable ASCII writes that cannot wrap the prompt.
func CanFastAppendShape(current string, cursor int, text string, columns int, currentLineWidth int) bool {
	if current == "" || cursor != len(current) || strings.Contains(current, "\n") {
		return false
	}
	if !isPrintableASCII(text) {
		return false
	}
	width := columns
	if width < 1 {
		width = 1
	}
	return currentLineWidth+len(text) < width
}

// CanFastBackspaceShape mirrors Hermes' conservative fast-echo delete gate.
// The optional columns argument preserves legacy behavior when omitted.
func CanFastBackspaceShape(current string, cursor int, columns ...int) bool {
	if current == "" || cursor <= 0 || cursor != len(current) || strings.Contains(current, "\n") {
		return false
	}
	if !isPrintableASCII(current) {
		return false
	}
	if len(columns) > 0 {
		width := columns[0]
		if width < 1 {
			width = 1
		}
		if cursor%width == 0 {
			return false
		}
	}
	return true
}

func SupportsFastEchoTerminal(env map[string]string) bool {
	return envmap.Value(env, "TERM_PROGRAM") != "Apple_Terminal"
}

func isPrintableASCII(s string) bool {
	if s == "" {
		return false
	}
	for i := 0; i < len(s); i++ {
		if s[i] < 0x20 || s[i] > 0x7e {
			return false
		}
	}
	return true
}

package composer

import "strings"

// IdleEditorPlaceholder is the prompt shown in the editor when no kernel turn
// is in flight. Tracks Hermes commit eaa7e2db's idle copy so operators see
// the same affordance whether they boot Gormes or Hermes.
const IdleEditorPlaceholder = "Type a message and hit Enter…"

// CancelHotkey is the busy-time interrupt hint appended to the running-agent
// placeholder.
const CancelHotkey = "Ctrl" + "+C cancel"

// RunningPlaceholder returns the editor placeholder text appropriate to the
// current in-flight state. When idle the prompt invites the next turn; while
// in flight it surfaces the always-on interrupt affordance, caller-provided
// busy slash commands, and the Ctrl+C cancel hint.
func RunningPlaceholder(inFlight bool, busySlashes []string) string {
	if !inFlight {
		return IdleEditorPlaceholder
	}

	parts := []string{"msg=interrupt"}
	for _, name := range busySlashes {
		name = strings.TrimSpace(name)
		if name == "" {
			continue
		}
		parts = append(parts, "/"+strings.TrimPrefix(name, "/"))
	}
	parts = append(parts, CancelHotkey)
	return strings.Join(parts, " · ")
}

package composer

import (
	"io/fs"
	"path/filepath"
	"strings"
	"testing"
	"time"
	"unicode/utf8"
)

func TestDetectComposerDroppedFileAcceptsQuotedRelativePaths(t *testing.T) {
	wantPath := filepath.Clean("./quoted name.txt")
	var statPath string
	got := DetectComposerDroppedFile(`"./quoted name.txt" describe it`, ComposerDropOptions{
		Stat: func(path string) (fs.FileInfo, error) {
			statPath = path
			if path == wantPath {
				return fakeComposerFileInfo{name: filepath.Base(path)}, nil
			}
			return nil, fs.ErrNotExist
		},
	})

	if !got.Matched || got.Path != wantPath || got.Remainder != "describe it" {
		t.Fatalf("DetectComposerDroppedFile quoted relative = %+v (statPath=%q), want matched path %q with remainder", got, statPath, wantPath)
	}
}

func TestDetectComposerDroppedFileTreatsTabsAsRemainderSeparator(t *testing.T) {
	wantPath := filepath.Clean("./drop.txt")
	var statPaths []string
	got := DetectComposerDroppedFile("./drop.txt\tdescribe it", ComposerDropOptions{
		Stat: func(path string) (fs.FileInfo, error) {
			statPaths = append(statPaths, path)
			if path == wantPath {
				return fakeComposerFileInfo{name: filepath.Base(path)}, nil
			}
			return nil, fs.ErrNotExist
		},
	})

	if !got.Matched || got.Path != wantPath || got.Remainder != "describe it" {
		t.Fatalf("DetectComposerDroppedFile tab-separated remainder = %+v (statPaths=%q), want matched path %q with remainder", got, statPaths, wantPath)
	}
}

func TestCollapseComposerPasteLabelPreservesUTF8(t *testing.T) {
	text := "a" + strings.Repeat("界", 30) + "\n" + strings.Repeat("emoji🙂", 30)

	got := CollapseComposerPaste(text, ComposerPasteOptions{LargePasteChars: 10, LargePasteLines: 99})
	if got.Snippet == nil {
		t.Fatal("CollapseComposerPaste did not create snippet for large paste")
	}
	if !utf8.ValidString(got.InsertText) {
		t.Fatalf("CollapseComposerPaste label is invalid UTF-8: %q", got.InsertText)
	}
	if got.Snippet.Text != text {
		t.Fatal("CollapseComposerPaste snippet text changed while making label")
	}
}

type fakeComposerFileInfo struct {
	name string
}

func (f fakeComposerFileInfo) Name() string       { return f.name }
func (f fakeComposerFileInfo) Size() int64        { return 1 }
func (f fakeComposerFileInfo) Mode() fs.FileMode  { return 0 }
func (f fakeComposerFileInfo) ModTime() time.Time { return time.Time{} }
func (f fakeComposerFileInfo) IsDir() bool        { return false }
func (f fakeComposerFileInfo) Sys() any           { return nil }

package composer

import (
	"strings"
	"testing"

	"github.com/TrebuchetDynamics/gormes-agent/internal/llm"
)

func TestHandleCopySlash(t *testing.T) {
	history := []llm.Message{
		{Role: "user", Content: "question"},
		{Role: "assistant", Content: "one"},
		{Role: "assistant", Content: "<think>hidden</think>Visible answer"},
	}

	latest := HandleCopySlash("/copy", history, true)
	if !latest.Handled || !latest.WriteClipboard || latest.Text != "Visible answer" || !strings.Contains(latest.Status, "#2") {
		t.Fatalf("HandleCopySlash latest = %+v, want clipboard write for visible response #2", latest)
	}

	first := HandleCopySlash("/copy 1", history, true)
	if !first.WriteClipboard || first.Text != "one" || !strings.Contains(first.Status, "#1") {
		t.Fatalf("HandleCopySlash first = %+v, want clipboard write for response #1", first)
	}

	invalid := HandleCopySlash("/copy 99", history, true)
	if invalid.WriteClipboard || invalid.Status != "copy: invalid response number" {
		t.Fatalf("HandleCopySlash invalid = %+v, want invalid-index status", invalid)
	}

	unavailable := HandleCopySlash("/copy", history, false)
	if unavailable.WriteClipboard || unavailable.Status != "copy: clipboard unavailable" {
		t.Fatalf("HandleCopySlash unavailable = %+v, want unavailable status", unavailable)
	}
}

package composer

import "testing"

func TestFastAppendShape(t *testing.T) {
	tests := []struct {
		name             string
		current          string
		cursor           int
		text             string
		columns          int
		currentLineWidth int
		want             bool
	}{
		{name: "ascii append fits", current: "hello", cursor: 5, text: "!", columns: 20, currentLineWidth: 5, want: true},
		{name: "cursor not at end", current: "hello", cursor: 3, text: "!", columns: 20, currentLineWidth: 5},
		{name: "empty current", current: "", cursor: 0, text: "a", columns: 20, currentLineWidth: 0},
		{name: "newline current", current: "hi\nthere", cursor: 8, text: "!", columns: 20, currentLineWidth: 5},
		{name: "wrap boundary", current: "hello", cursor: 5, text: "!", columns: 6, currentLineWidth: 5},
		{name: "ansi text", current: "hello", cursor: 5, text: "\x1b[31m", columns: 20, currentLineWidth: 5},
		{name: "tab text", current: "hello", cursor: 5, text: "\t", columns: 20, currentLineWidth: 5},
		{name: "latin1 text", current: "hello", cursor: 5, text: "é", columns: 20, currentLineWidth: 5},
		{name: "combining mark", current: "hello", cursor: 5, text: "e\u0301", columns: 20, currentLineWidth: 5},
		{name: "cjk text", current: "hello", cursor: 5, text: "界", columns: 20, currentLineWidth: 5},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			if got := CanFastAppendShape(tc.current, tc.cursor, tc.text, tc.columns, tc.currentLineWidth); got != tc.want {
				t.Fatalf("CanFastAppendShape() = %v, want %v", got, tc.want)
			}
		})
	}
}

func TestFastBackspaceShape(t *testing.T) {
	tests := []struct {
		name    string
		current string
		cursor  int
		columns []int
		want    bool
	}{
		{name: "ascii delete", current: "hello", cursor: 5, columns: []int{20}, want: true},
		{name: "cursor not at end", current: "hello", cursor: 3, columns: []int{20}},
		{name: "empty", current: "", cursor: 0, columns: []int{20}},
		{name: "newline", current: "hi\nthere", cursor: 8, columns: []int{20}},
		{name: "cjk", current: "hi界", cursor: 5, columns: []int{20}},
		{name: "combining mark", current: "hie\u0301", cursor: 5, columns: []int{20}},
		{name: "emoji", current: "hi🙂", cursor: 6, columns: []int{20}},
		{name: "wrap boundary rejected", current: "hello ", cursor: 6, columns: []int{6}},
		{name: "double wrap boundary rejected", current: "abcdefghijkl", cursor: 12, columns: []int{6}},
